pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strict dead-space avoidance: penalize unusable small gaps hard.
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item (<= ~10)
    // are pure waste; quadratically punish them.
    if post_residual < 10 {
        score += (10.0 - post_residual as f64) * 40.0;
    } else if post_residual < 20 {
        // Small gaps may still fit tiny items; mild penalty.
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (low post_residual) extra.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Post residual can't host next item: mild penalty scaled by gap size.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when there are already many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "leftover" bin; prefer consuming such bins.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.5;

    // New-bin candidate handling: an empty bin gets a neutral-ish baseline;
    // penalize opening a new bin when decent fits exist, but allow it when
    // the item would leave a huge dead gap in any existing bin.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: mid-range post residual equivalent.
        score = (bin_capacity - item_size) as f64 * 1.2 + open_bins_count as f64 * 0.5;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If item is large, a fresh bin wastes less capacity.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let item = item_size as f64;
    let itemn = item / cap;
    let mean_r = mean_residual / cap;
    let next = next_item_size as f64;

    // Base: quadratic penalty on post residual, modulated by stream progress
    let mut score = prn * (1.0 + 2.0 * prn) * (1.0 + progress);

    // Non-linear coupling: post residual vs item size interaction
    score -= 1.5 * itemn * (1.0 - prn) * (1.0 - prn);

    // Harmonized bins: penalize deviation from mean residual
    let dev = prn - mean_r;
    score += 0.8 * dev * dev;

    // Lookahead: reward exact / near-exact chain with next item (absolute units)
    if next > 0.0 && next <= pr {
        let chain_waste = pr - next;
        score -= (18.0 - 0.15 * chain_waste) * (1.0 + 0.5 * progress);
        if chain_waste == 0.0 {
            score -= 25.0;
        } else if chain_waste <= 3.0 && pr <= 30.0 {
            score -= 5.0;
        }
    } else if next > pr {
        // Gap penalty scaled by scarcity of fitting bins
        let gap = (next - pr).min(60.0);
        let gp = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.33 } else { 0.28 };
        score += gp * gap / cap * cap; // keep absolute scale for gaps
    }

    // Tight-fit bonus: item nearly fills the bin
    if pr >= item {
        let fill_ratio = item / pr.max(1.0);
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    } else {
        // Item cannot fit: penalize (should rarely be selected)
        score += 12.0;
    }

    // Last-chance bin bonus (smooth, stronger late in the stream)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Prefer tighter fits overall
    score += 0.5 * itemn * prn;

    // NEW-BIN CANDIDATE handling: open a fresh bin only when no open bin is a good host
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item && (pr - item) < 8.0;
        if tight_exists {
            score += 40.0; // an open bin gives near-perfect fit; reject new bin
        } else if pr < item {
            score -= 5.0; // no open bin fits: prefer opening a new one
        } else {
            // Open bins fit but poorly; open a new bin especially for large items
            score += 6.0 * (1.0 - progress);
            if item >= 0.6 * cap && pr >= item {
                score += 10.0;
            }
            if next > 0.0 && next <= pr && (pr - next) < 5.0 {
                score -= 12.0;
            }
        }
    }

    // Large residual bins that cannot serve the next item: discourage hoarding space
    if pr >= item && pr >= 50.0 && next > pr {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Dead-space avoidance: heavy penalty for tiny unusable gaps.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * 6.0;
    } else if pr >= 20 && pr <= 25 {
        score += 10.0;
    } else if pr <= 33 {
        score -= 2.0;
    } else if pr <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Tightness reward, nonlinear.
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure (mild).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0; // an open bin fits nearly perfectly; never open new
        } else if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 * (1.0 - 0.4 * progress);
        }
        // Borrowed from best: if a new bin would still leave a near-perfect
        // chain for the next item, opening is cheaper than wasting residual.
        if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
            score -= 12.0;
        }
    }

    // Lookahead: reward placements that let the next item chain into this bin.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0; // perfect chain
            }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 {
                score -= 6.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
            // Two-step lookahead: chain must also leave room for residual reuse.
            if chain_waste > 5.0 && chain_waste <= 12.0 && mean_residual > (pr as f64) * 1.5 {
                score -= 2.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Fill ratio bonus: strong fits into the current residual.
    if pr >= item_size {
        let fill_ratio = item_size as f64 / pr.max(1) as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
        if (pr - item_size) < 4 {
            score -= 4.0;
        }
        // Large leftover relative to capacity is wasteful when alternatives exist.
        if (pr - item_size) as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 1 {
            score += 3.0;
        }
    } else if pr > 0 {
        score += 12.0; // creates a gap smaller than the item itself
    }

    // Prefer fuller existing bins (borrowed from best).
    let fill_ratio_bin = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio_bin > 0.85 {
        score -= 6.0 * fill_ratio_bin;
    } else if fill_ratio_bin < 0.35 && pr > item_size {
        score += 3.0;
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr as f64) * 0.1;
    score -= progress * 5.0 * tightness;

    // Few-fitting-bins consolidation pressure.
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills what's left.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 15.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap * 0.15;
        }
    }

    // Compare against mean residual: favor bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a loose fit.
    if fitting_bins_count == 1 {
        score -= 6.0 * fit_ratio;
        if post_residual < 10 {
            score -= 5.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline, penalize so open bins with tight fits win.
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pair fits nicely in a fresh bin: make fresh bin competitive.
            score -= 18.0;
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins over opening more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    } else {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (1..=10) are nearly worthless; penalize them hard.
    let dead_zone = 10u32;
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 25.0;
    }

    // Gaps that cannot fit the known next item are also risky (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 1.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive if it avoids a very poor fit.
        let poor_fit = (post_residual as f64) > (item_size as f64 * 0.9)
            && post_residual > dead_zone;
        if poor_fit {
            score -= 5.0; // new bin keeps a large usable gap
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    } else {
        // Existing bin: mild reward for being a "last chance" bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins whose residual is already small (tight fits first).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Slight global pressure: fewer open bins relative to progress favors reuse.
    score += open_bins_count as f64 * 0.3
        * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if post_residual <= 10 {
            score += 60.0 * (11.0 - dead); // worst: gap of 1..10 is wasted
        } else if post_residual < 20 {
            score += 20.0; // likely dead unless small items follow
        }
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit bonus relative to current item size.
    score -= (item_size as f64) * 0.15;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: consolidate when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // If next item fits the post residual, this placement is excellent.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit the post residual, the gap may become dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: prefer it only when open bins are numerous and residual is poor.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap > 15.0 {
            score -= 10.0; // existing bins have plenty of room, opening is fine anyway
        } else {
            score += 12.0; // prefer filling existing bins before opening
        }
        score += step_index as f64 / total_items.max(1) as f64 * 5.0;
    }

    // Slight preference for bins with residual close to item size (good fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Strong reward for very small residuals (near-perfect fits) — borrowed threshold idea
    if post_residual < 10 {
        score -= 45.0;
    } else if post_residual <= 12 {
        score += 30.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 33 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Penalize residual that cannot fit the lookahead item (smooth quadratic + gap penalty)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr).min(60.0);
            let gap_frac = gap / cap;
            score += 12.0 * gap_frac * gap_frac * cap;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap;
        } else {
            let slack = (pr - ni) / cap;
            score -= 6.0 * slack * (1.0 - slack);
            // Perfect chain fit bonus
            if pr == ni {
                score -= 30.0;
            }
            if (pr - ni) <= 5.0 && pr <= 30.0 {
                score -= 4.0;
            }
        }
    }

    // Reward tight fits: smooth polynomial in fill ratio
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 + progress);

    // High fill ratio relative to residual (tight packing into existing bin)
    if post_residual >= item_size {
        let fill_ratio = item_size as f64 / post_residual as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    }

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin decision: prefer opening a fresh bin only when no tight fit exists
    if bin_residual == bin_capacity {
        let tight_exists = post_residual >= item_size && (post_residual - item_size) < 8;
        if tight_exists {
            score += 40.0; // never open a new bin when a tight fit exists
        } else if post_residual < item_size {
            score -= 5.0;
        } else {
            score += 6.0 * (1.0 - progress) * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && post_residual >= item_size {
                score += 10.0;
            }
        }
    }

    // Item cannot fit this bin at all: strong penalty
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Penalize bins whose residual will be stranded against the lookahead item
    if post_residual >= item_size && post_residual >= 50 && next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual with smooth coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Fine-grained residual tiers
    if post_residual < 10 {
        score -= 45.0;
    } else if post_residual <= 12 {
        score += 30.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 33 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: chain-fit reward with graded small-waste bonuses
    if next_item_size > 0 {
        if next_item_size as u32 <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if post_residual == next_item_size {
                score -= 30.0;
            }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 {
                score -= 6.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && post_residual <= 30 {
                score -= 4.0;
            }
            if chain_waste > 0.0 && chain_waste <= 2.0 && post_residual <= 15 {
                score -= 3.0;
            }
            if chain_waste > 0.0 && chain_waste < 4.0 {
                score -= 2.5;
            }
        } else {
            let gap = ((next_item_size as f64) - pr).min(60.0);
            let gap_frac = gap / cap;
            score += 12.0 * gap_frac * gap_frac * cap;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap;
        }
    }

    // Reward tight fits via fill ratio
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 + progress);

    // High fill ratio relative to residual
    if post_residual >= item_size {
        let fill_ratio = item_size as f64 / post_residual as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    }

    // Scarce-fit bonus
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 8.0;
    }

    // Last-chance bin bonus (damped by progress)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Fragmentation penalty vs mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin decision logic
    if bin_residual == bin_capacity {
        let tight_exists = post_residual >= item_size && (post_residual - item_size) < 8;
        if tight_exists {
            score += 40.0;
        } else if post_residual < item_size {
            score -= 5.0;
        } else {
            score += 6.0 * (1.0 - progress) * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && post_residual >= item_size {
                score += 10.0;
            }
            if item_size as f64 >= 0.8 * cap {
                score += 6.0;
            }
            if next_item_size > 0 && next_item_size as u32 <= post_residual && (post_residual - next_item_size) < 5 {
                score -= 12.0;
            }
        }
    }

    // Item cannot fit: strong penalty
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Stranded residual vs lookahead
    if post_residual >= item_size && post_residual >= 50 && next_item_size > 0 && next_item_size as u32 > post_residual {
        score += 5.0;
    }

    // Large leftover after this item: mild penalty when alternatives exist
    if post_residual >= item_size && (post_residual - item_size) as f64 > 0.35 * cap && fitting_bins_count > 1 {
        score += 3.0;
    }

    // Prefer bins below mean residual when residual is large (reduce dead space)
    if post_residual >= item_size && post_residual > 40 && mean_residual < pr {
        score -= 1.5;
    }

    score
}

