    // New-bin candidate: make it attractive only for big items with poor fits
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / cap) * (item_size as f64 / cap);
        score += 15.0 * (1.0 - tightness) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space ---
    // Residuals partitioned into harmonic classes of capacity fractions (1/2, 1/3, 1/4 of C).
    // Leftovers that cannot absorb the smallest plausible item (<=10) are dead space: heavy penalty.
    if post_residual < 10 {
        score -= 45.0; // near-perfect packing, excellent
    } else if post_residual <= 12 {
        score += 30.0; // dangerous sliver: blocks everything, worst class
    } else if post_residual <= 25 {
        score += 10.0; // quarter-bin class: only tiny items fit
    } else if post_residual <= 33 {
        score -= 2.0; // third-bin class
    } else if post_residual <= 50 {
        score -= 8.0; // half-bin class: very reusable
    } else {
        score -= 4.0; // large residual, still flexible
    }

    // Integer-division harmonic: leftover divisible by common item sizes is more reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0) {
        score -= 6.0;
    }
    // Odd prime-ish leftovers (e.g. 37, 41, 53) tend to be awkward.
    if pr > 12 && pr < 90 && pr % 10 != 0 && pr % 5 != 0 {
        score += 4.0;
    }

    // --- Lookahead coupling: does the next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains perfectly: strong reward, scaled by how snugly it chains.
            let chain_waste = (pr - next_item_size) as f64;
            score -= 20.0 - 0.25 * chain_waste;
            // Harmonic bonus: next item exactly fills a class boundary (perfect closure).
            if pr == next_item_size {
                score -= 25.0;
            }
        } else {
            // Next item cannot use this bin's leftover; penalize by the shortfall's class.
            let gap = (next_item_size - pr) as f64;
            score += 0.30 * gap.min(60.0);
        }
    }

    // --- Last-chance pressure: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // --- Late-stream consolidation: near the end, close bins tightly rather than opening ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0; // new empty bins get progressively less attractive

    // --- Spread control: avoid piling onto bins far from the mean residual ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild reward for filling a large fraction of the bin with this item.
    score -= 0.10 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1)
    // can't happen, but small residuals (< ~20) are hard to fill later.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0; // heavy penalty for tiny gaps
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize using existing bins when many are open,
    // but only mildly, so dead-space avoidance still dominates.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: make empty bin attractive only when the
    // item is large and would leave an awkward gap elsewhere.
    if bin_residual == bin_capacity {
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // large item: fresh bin is fine
        } else {
            score += 25.0; // small item: prefer existing bins
        }
    }

    // Lookahead: if next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates unusable gap for the known next item
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.1;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 40.0;
        } else if (post_residual as u32) < next_item_size {
            // Dead space: next item cannot follow in this bin.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.6;
        } else {
            // Next item fits but imperfectly: mild reward scaled by closeness.
            score -= (20.0 - diff as f64).max(0.0) * 0.5;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than average (good fits), penalize loose bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New empty bin candidate: penalize unless few bins open or residual is very tight.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening fresh bins is less harmful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Small bonus for filling bins almost completely.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= fill * fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward heavily; if next item cannot fit in post-residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else {
            score -= 3.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else. A fresh bin should only win on tight fits
    // or when post-residual is very small (rare perfect-ish placement).
    if bin_residual == bin_capacity {
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        } else if post_residual <= 20 {
            score -= 30.0; // near-perfect packing justifies a new bin
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state: many open bins with slack -> prefer using existing slack.
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64).ln();
        if (bin_residual as f64) > mean_residual * 1.5 {
            score -= 8.0; // this bin is unusually slack; drain it
        }
    }

    // Small absolute post-residual is dead space; penalize tiny leftovers
    // that are unlikely to fit future items (below min item size 1..100 unknown,
    // so use soft quadratic penalty).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins tightly (penalize large residuals quadratically).
    // Late: relax, since leftover fragmentation matters less.
    let poly = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += poly;

    // Smooth cubic term: mid-stream, strongly prefer near-zero residuals.
    let cubic = norm_pr.powi(3) * progress * (1.0 - progress) * 4.0 * cap;
    score += cubic;

    // Reward tight fits (small post_residual) with a smooth exponential bonus.
    let tight = (-norm_pr * 6.0).exp() * (1.0 + progress) * 4.0;
    score -= tight;

    // Last-chance bin: strong smooth bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: bonus if next item fits into the resulting residual.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 5.0 * (1.0 - fit_frac) * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that wastes space for the next item.
        score += 3.0 * (1.0 - progress) * (pr / cap);
    }

    // New-bin candidate: prefer it only when open bins are crowded or residual is huge.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let mean_norm = mean_residual / cap;
        score = 8.0 + 15.0 * mean_norm * (1.0 - progress) + 20.0 * (1.0 - crowd);
        // Late stream: opening fresh bins is cheaper than fragmenting.
        score -= 10.0 * progress * progress;
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual too small to ever be usable (min item = 1 here, but
    // tiny slivers are statistically unlikely to be filled by future draws).
    if post_residual < 5 {
        score += 200.0; // near-wasted bin
    } else if post_residual <= 10 {
        score += 60.0;
    }

    // Harmonic class reward: post_residual divisible by common item granularities
    // (classes mod 10) tends to admit future items exactly.
    let pr = post_residual as i64;
    let exact_fit_bonus = if pr % 10 == 0 { 25.0 }
        else if pr % 5 == 0 { 12.0 }
        else if pr % 2 == 0 { 4.0 }
        else { 0.0 };
    score -= exact_fit_bonus;

    // Lookahead coupling: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic alignment of leftover after next placement
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this bin's residue: penalize proportionally
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // current item leaves a large residue AND no good exact-fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Neutralize the raw post_residual (= capacity) advantage, add a modest
        // opening cost so tight fits in existing bins win.
        score = bin_capacity as f64 * 0.9 + 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a new bin is decent if the next item pairs well with a fresh capacity
            score -= 10.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Late in the stream, be more conservative: keep bins tight, avoid sprawl.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Slight tie-break toward bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..=100, assume min ~10).
    // Scale penalty sharply as post_residual falls into the dead zone.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Penalize mid-range awkward residuals (hard to fill later) less than tiny gaps but still penalize.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (post_residual near 0 but not dead-zone zero waste).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open bins pressure: discourage spreading across too many bins; favor filling existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it
    // (avoid opening a new bin) unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
        // If post fit leaves a large usable gap, extra reward.
        if post_residual >= 25 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if next item fits into the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
        // Next item won't fit in the leftover: penalize creating stranded space.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from the mean
    // (i.e., this bin is tighter than average -> fill it).
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.4;
    }

    // New-bin candidate handling: make opening a new bin costly unless all fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0 + open_bins_count as f64 * 0.5;
        // If next item is large and this item leaves a good complementary gap, allow it.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight stream progression term: later in the stream, be more conservative about gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty curve.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful again
    // (below the minimum item size of 1, but practically below ~15 is risky).
    if post_residual < 15 {
        score += (15 - post_residual) as f64 * 3.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement; if next item cannot fit post_residual but could
    // fit other residuals, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let gap = (post_residual as u32 - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 + 0.1 * nxt;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling open
    // bins); late in the stream, exact fits matter most anyway.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> discourage
    // spreading items into fresh bins; prefer bins below mean residual
    // (filling the emptiest-ish bins balances residual distribution).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are already many open
        // bins and when mean residual is large (lots of slack available).
        score += 20.0 + 4.0 * open_bins_count as f64 + 0.5 * mean_residual.max(0.0);
        // But if nothing fits well anywhere (post_residual huge relative to
        // item), opening a new bin can win — soften the penalty.
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality < 0.35 {
            score -= 25.0;
        }
    } else {
        // Prefer bins whose residual is below the mean (tighter bins first).
        let diff = mean_residual - bin_residual as f64;
        score -= 0.15 * diff;
    }

    // Mild penalty for very large item into nearly full bin creating slivers.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize residual that cannot fit the lookahead item (smooth quadratic)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr) / cap;
            score += 12.0 * gap * gap * cap;
        } else {
            let slack = (pr - ni) / cap;
            score -= 6.0 * slack * (1.0 - slack);
        }
    }

    // Reward tight fits: smooth polynomial in fill ratio
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 + progress);

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual into capacity fractions (harmonic bins).
    let frac = pr / cap;
    if frac < 0.10 {
        score -= 50.0; // tiny dead space, acceptable
    } else if frac < 0.25 {
        score -= 10.0;
    } else if frac < 0.50 {
        score += 15.0;
    } else {
        score += 40.0; // wasting more than half a bin
    }

    // Modulo arithmetic: residuals divisible by common item sizes are reusable.
    if post_residual > 0 {
        let mut reusable = 0u32;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reusable += 1;
            }
        }
        score -= 20.0 * reusable as f64;
    }

    // Lookahead coupling: can the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt_frac = (post_residual - next_item_size) as f64 / cap;
            score += 30.0 * nxt_frac;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 50.0 * (1.0 - crowding) - 30.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 40.0;
        }
    }

    score
}

