            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Post residual can't host next item: mild penalty scaled by gap size.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when there are already many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "leftover" bin; prefer consuming such bins.
    let residual_diff = mean_residual - bin_residual as f64;
    score += residual_diff * 0.5;

    // New-bin candidate handling: an empty bin gets a neutral-ish baseline;
    // penalize opening a new bin when decent fits exist, but allow it when
    // the item would leave a huge dead gap in any existing bin.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: mid-range post residual equivalent.
        score = (bin_capacity - item_size) as f64 * 1.2 + open_bins_count as f64 * 0.5;
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If item is large, a fresh bin wastes less capacity.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fit (small post_residual already rewarded by base).

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)) * (next_item_size as f64 / 100.0);
        // Penalize leaving a gap that neither fits next item nor is useful.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Reward chains: post_residual fits next item AND next residual is reusable.
        if next_item_size <= post_residual {
            let second_residual = post_residual - next_item_size;
            if second_residual < 10 {
                score -= 6.0; // perfectly consumed bin
            }
        }
    }

    // Dead-space penalty: residuals too small for any item (min size 1, but tiny gaps waste).
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when fits are poor elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // More attractive when many open bins are fragmented (high mean residual spread)
        // or when current bin would leave a bad gap.
        if post_residual < 10 {
            score -= 30.0; // prefer fresh bin over creating dead space
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If open bins are mostly full (low mean residual), a new bin is natural.
        score -= (mean_residual - 30.0).max(0.0) * 0.2;
    }

    // Mild preference for fuller bins relative to fleet state.
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize creating tiny dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when many bins
    // are open and mean residual is low; discourage unless current bins are full-ish.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with stream progress (commitment).
        score += 25.0 + 15.0 * (step_index as f64 / total_items.max(1) as f64);
        // If mean residual across open bins is small, opening new bins is fine.
        score -= mean_residual * 0.4;
        // If few open bins, opening is cheap.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    } else {
        // Slight preference to fill already-open bins as stream progresses.
        score -= 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Discourage placing large items into very full bins when other options exist
    // (they'd leave no flexibility), but encourage exact-ish fits regardless.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 6.0;
    } else if fill_ratio < 0.3 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    let pr = post_residual ;
    if post_residual < 10 { score -= 45.0 ; }
    else if post_residual <= 12 { score += 30.0 ; }
    else if post_residual <= 25 { score += 10.0 ; }
    else if post_residual <= 33 { score -= 2.0 ; }
    else if post_residual <= 50 { score -= 8.0 ; }
    else { score -= 4.0 ; }

    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64 ;
            score -= 22.0 - 0.22 * chain_waste ;
            if pr == next_item_size { score -= 30.0 ; }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 { score -= 6.0 ; }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 { score -= 4.0 ; }
            // new: prefer chains that leave residuals matching common small-item sizes
            let nr = next_item_size as f64 ;
            if chain_waste > 0.0 && (nr * 2.0 <= pr as f64) && pr <= 40 { score -= 3.0 ; }
        } else {
            let gap = (next_item_size - pr) as f64 ;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 } ;
            score += gap_penalty * gap . min (60.0) ;
        }
    }

    if fitting_bins_count <= 2 && pr >= item_size { score -= 8.0 ; }

    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8 ;
        if tight_exists { score += 40.0 ; }
        else if pr < item_size { score -= 5.0 ; }
        else {
            let progress = step_index as f64 / total_items . max (1) as f64 ;
            score += 6.0 * (1.0 - progress) ;
            if item_size as f64 >= 0.6 * bin_capacity as f64 && pr >= item_size { score += 10.0 ; }
            // new: opening a fresh bin is more attractive when open bins are fragmented
            if mean_residual > 25.0 && fitting_bins_count > 2 { score -= 4.0 ; }
        }
    }

    if pr > 0 && pr < item_size { score += 12.0 ; }
    if pr >= item_size && pr >= 50 && next_item_size > 0 && next_item_size > pr { score += 5.0 ; }

    let fill_ratio = item_size as f64 / pr . max (1) as f64 ;
    if pr >= item_size && fill_ratio > 0.85 { score -= 7.0 * (fill_ratio - 0.85) / 0.15 ; }

    // new: penalize leaving residuals in the awkward 13..=17 dead zone
    if pr >= 13 && pr <= 17 && next_item_size > pr { score += 6.0 ; }
    // new: reward near-perfect fills even more when few bins remain open
    if pr == 0 && fitting_bins_count <= 3 { score -= 4.0 ; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late in the stream, penalize dead space more.
    let progress_coupling = (pr / cap).powi(2) * (1.0 + 2.0 * progress) * 30.0;
    score += progress_coupling;

    // Reward near-perfect fills with a smooth bell-shaped bonus.
    let fill = 1.0 - pr / cap;
    score -= 25.0 * (-((fill - 1.0).powi(2)) * 8.0).exp() * fill;

    // Penalize opening a new bin when existing bins fit, more strongly late in stream.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 40.0 + 60.0 * progress;
    }

    // Last-chance bin: strong smooth reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap).max(0.0);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for deviating from mean residual (keeps bin spread balanced).
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: tight fits preferred, non-linearly scaled.
    let mut score = pr + 40.0 * pr_norm * pr_norm * cap;

    // Stream-progress coupling (smoothstep gain 1 -> 3).
    let g = 1.0 + 2.0 * progress * progress * (3.0 - 2.0 * progress);
    score += g * 25.0 * pr_norm * pr_norm * pr_norm * cap;

    // Discrete tightness bands (borrowed from best): exact-match and near-exact
    // placements get strong rewards; mid-range leftovers get graded bonuses.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual <= 12 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    } else if post_residual <= 33 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bin: strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // New empty bin candidate: penalize unless a tight fit exists in the
    // current bin context or the item is large (better in a fresh bin).
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        let lookahead = (next_item_size as f64 / cap).clamp(0.0, 1.0);
        let relax = 1.0 - (0.6 * mean_norm + 0.4 * lookahead * progress).min(0.9);
        let mut pen = 35.0 * relax + 20.0 * (1.0 - progress);
        // Large items are better placed in a fresh bin (avoid fragmentation).
        if (item_size as f64) >= 0.6 * cap {
            pen -= 15.0;
        }
        score += pen;
    }

    // Lookahead: reward bins whose post-residual can host the next item;
    // penalize dead space proportionally to waste, scaled by progress.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let chain_waste = pr - next_item_size as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if chain_waste == 0.0 {
                score -= 30.0; // perfect chaining
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30.0 {
                score -= 4.0;
            }
        } else {
            let gap = (next_item_size as f64 - pr).min(60.0);
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap * (1.0 - 0.3 * progress);
        }
    }

    // Mild penalty when bin is far below mean residual (unbalanced usage).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * (0.5 + 0.5 * progress);

    // High fill-ratio bonus.
    if post_residual >= item_size {
        let fill_ratio = item_size as f64 / pr.max(1.0);
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    }

    // Few fitting bins: reward using this one to avoid opening new bins.
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Modulo-10 class of post_residual: small residues are "dead space" classes.
    let mod_class = (post_residual % 10) as f64;
    // Penalize awkward residues (1..9) that waste space; reward exact multiples of 10.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else {
        score += mod_class * 0.35;
    }

    // Integer-division thresholds: how many "unit slots" of 10 remain.
    let slots = post_residual / 10;
    // Reward bins whose leftover can host typical future items.
    score -= slots as f64 * 0.8;

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Fractional fit quality of the lookahead.
            let fit_q = next_item_size as f64 / pr;
            score -= 10.0 * fit_q;
        } else {
            // Next item does not fit here: mild penalty scaled by how far off.
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over.min(40.0);
        }
        // Harmonic pairing: (next_item_size + item_size) modulo capacity quarters.
        let pair = (item_size + next_item_size) % 25;
        if pair == 0 {
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.2 * (pr.min(50.0));
    }

    // New-bin candidate handling: an empty bin gets a baseline cost so it wins only
    // when all open bins have poor fits (their scores would be even higher).
    if bin_residual == bin_capacity {
        score = cap * 0.55 - 0.10 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Slight discount if the fresh bin perfectly hosts the lookahead later.
            let _ = frac;
        }
    } else {
        // Prefer fuller bins: reward small post residual relative to mean residual.
        if mean_residual > 0.0 {
            let rel = pr / mean_residual;
            if rel < 1.0 {
                score -= 5.0 * (1.0 - rel);
            } else {
                score += 3.0 * (rel - 1.0).min(2.0);
            }
        }
        // Late in the stream, tighten packing: penalize large leftovers more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * frac * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
