pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 150.0; // perfect fit strongly rewarded
    }

    // Penalize moderate waste proportionally to how unusable it is.
    if post_residual >= 10 {
        // gap is reusable if it can hold a plausible item; penalize gaps in [10,30) less harshly
        let gap = post_residual as f64;
        score += 0.3 * gap * (1.0 - gap / bin_capacity as f64);
    }

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (item_size as f64);
        score -= 30.0 * tightness.max(0.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins;
    // the new-bin candidate (residual == capacity) gets penalized via open_bins_count.
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // but allow new bin if current fit would create dead space
        if post_residual > 0 && post_residual < 10 && bin_residual >= item_size {
            score -= 250.0;
        }
    } else {
        // using an existing bin relieves pressure
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // If next item would not fit in post_residual but post_residual is tiny, already penalized above.

    // Late in the stream, consolidate: prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 60.0 * progress;
    } else {
        score -= 40.0 * progress;
    }

    // Mild preference for bins with low residual (fill fullest bins first).
    score += 0.1 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
