    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Small-residual ladder (borrowed idea, tuned): strong reward for near-zero waste.
    if pr > 0 {
        if pr <= 10 {
            score -= 45.0;
        } else if pr <= 12 {
            score += 30.0;
        } else if pr <= 25 {
            score += 10.0;
        } else if pr <= 33 {
            score -= 2.0;
        } else if pr <= 50 {
            score -= 8.0;
        } else {
            score -= 4.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure (mild).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0; // an open bin fits nearly perfectly; never open new
        } else if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 + 6.0 * (1.0 - progress);
        }
    }

    // Lookahead: reward placements that let the next item chain into this bin.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0; // perfect chain
            }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 {
                score -= 6.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
        } else if pr > 0 {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Fill ratio bonus: strong fits into the current residual.
    if pr >= item_size {
        let fill_ratio = item_size as f64 / pr.max(1) as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    } else if pr > 0 {
        score += 12.0; // creates a gap smaller than the item itself
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr as f64) * 0.1;
    score -= progress * 5.0 * tightness;

    // Scarcity bonus: prefer conserving bins when few alternatives fit.
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // ideal chain: this bin is consumed perfectly by next item
        } else if post_residual as f64 > nxt {
            score -= 15.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // next item cannot fit here: dead space penalty grows with wasted space
            score += 0.5 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: just prefer minimal waste
        score += 0.1 * post_residual as f64;
    }

    // Prefer bins tighter than the mean residual (fill crowded bins first).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.2 * open_bins_count as f64;
        // If the next item could exactly fill a fresh bin with the current item,
        // soften the penalty a bit (opening may enable a perfect chain).
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Progress factor: later in the stream, be greedier about closing gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Strong reward for very small residuals (near-perfect fits) — borrowed threshold idea
    if post_residual < 10 {
        score -= 45.0;
    } else if post_residual <= 12 {
        score += 30.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 33 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Penalize residual that cannot fit the lookahead item (smooth quadratic + gap penalty)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr).min(60.0);
            let gap_frac = gap / cap;
            score += 12.0 * gap_frac * gap_frac * cap;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap;
        } else {
            let slack = (pr - ni) / cap;
            score -= 6.0 * slack * (1.0 - slack);
            // Perfect chain fit bonus
            if pr == ni {
                score -= 30.0;
            }
            if (pr - ni) <= 5.0 && pr <= 30.0 {
                score -= 4.0;
            }
        }
    }

    // Reward tight fits: smooth polynomial in fill ratio
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 + progress);

    // High fill ratio relative to residual (tight packing into existing bin)
    if post_residual >= item_size {
        let fill_ratio = item_size as f64 / post_residual as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
    }

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin decision: prefer opening a fresh bin only when no tight fit exists
    if bin_residual == bin_capacity {
        let tight_exists = post_residual >= item_size && (post_residual - item_size) < 8;
        if tight_exists {
            score += 40.0; // never open a new bin when a tight fit exists
        } else if post_residual < item_size {
            score -= 5.0;
        } else {
            score += 6.0 * (1.0 - progress) * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && post_residual >= item_size {
                score += 10.0;
            }
        }
    }

    // Item cannot fit this bin at all: strong penalty
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Penalize bins whose residual will be stranded against the lookahead item
    if post_residual >= item_size && post_residual >= 50 && next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= 40.0 * ((cap - pr) / cap).powi(3);

    // Penalize dead space that no future item can use.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size as f64 == pr {
            score -= 60.0;
        } else if (next_item_size as u32) <= post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here; wasted small residual is worse late in stream
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * t * (pr / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Mild penalty for opening new bins when many open bins exist and item is small.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        let waste = pr / cap;
        score += 20.0 + 30.0 * t - 20.0 * waste;
        // Favor new bins for large items early (they create useful big residual)
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Encourage consolidation when many bins are open.
    score += 0.3 * open_bins_count as f64 * (1.0 - (bin_residual as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let item = item_size as f64 / cap;
    let mean_r = mean_residual / cap;
    let next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress
    let mut score = pr * (1.0 + 2.0 * pr) * (1.0 + progress);

    // Non-linear coupling: post residual vs item size interaction
    score -= 1.5 * item * (1.0 - pr) * (1.0 - pr);

    // Favor bins whose residual is close to the mean residual (harmonized bins)
    let dev = pr - mean_r;
    score += 0.8 * dev * dev;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next > 0.0 {
        let gap = (pr - next).abs();
        score -= 1.2 * (1.0 - gap.min(1.0)) * pr;
    }

    // Last-chance bin bonus (smooth, stronger late in the stream)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Prefer tighter fits overall
    score += 0.5 * item * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers that are "usable" (>= 20, enough
    // for small items) are rewarded; tiny dead space (< 20) is penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement
    let frac = pr / cap;

    // Integer-division thresholds: dead space classes
    if post_residual == 0 {
        // Perfect fit: strongest reward
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (< smallest item) — heavy penalty
        score += 35.0;
    } else if post_residual < 20 {
        // Only fits tiny items — moderate penalty
        score += 12.0;
    } else {
        // Usable leftover: reward proportional to harmonic class quality.
        // Class by which capacity-fraction band the residual falls in.
        if frac >= 0.5 {
            score -= 20.0; // half-full bin leftover: very reusable
        } else if frac >= 0.3 {
            score -= 10.0;
        } else if frac >= 0.15 {
            score -= 3.0;
        }
        // Fine-grained modulo refinement: residuals divisible by common
        // item-size classes (multiples of 10) pair well with future items.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves new dead space — small penalty
            // scaled by how much would remain.
            let nr = post_residual - next_item_size;
            if nr < 10 {
                score += 6.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item will NOT fit here: if this is the only fitting bin,
            // penalize less (we must use it anyway); otherwise penalize a
            // bit since another bin may serve both items better.
            let tight = (fitting_bins_count as f64).max(1.0);
            score += 8.0 / tight;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when the
    // current item is large and open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; make it attractive when open-bin
        // placements would waste a lot (post_residual small but nonzero).
        if post_residual == 0 {
            // Fresh bin with item = full capacity match (rare)
            score -= 15.0;
        }
        // Prefer opening new bins early in the stream when few bins exist,
        // and for large items where residual fragmentation is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 {
            score -= 10.0 * (1.0 - progress);
        }
        // Slight preference for new bins when existing residuals are fragmented
        if mean_residual < (item_size as f64) {
            score -= 5.0;
        }
    } else {
        // Reusing an open bin: reward keeping the number of open bins low
        // early on, but avoid cramming when it creates tiny dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress) * (open_bins_count as f64).min(10.0) / 10.0;
    }

    // Mean-residual coupling: placing into a bin whose residual is close to
    // the mean keeps the bin population balanced; reward tightness of fit.
    let fit_tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * fit_tightness;

    // Harmonic class of item size: large items (>= half capacity) should be
    // placed as tightly as possible — reward bins where they leave <= 20.
    if item_size >= bin_capacity / 2 && post_residual <= 20 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Modulo class penalty: if post_residual is an "awkward" size that no
    // common item class (10..=80 step 10) matches well, nudge score up.
    if post_residual > 0 && post_residual < bin_capacity {
        let mut best_match = 0u32;
        for cls in [10u32, 20, 30, 40, 50, 60, 70, 80] {
            if cls <= post_residual && cls > best_match {
                best_match = cls;
            }
        }
        let waste = post_residual - best_match;
        if waste > 0 && waste < 10 {
            score += waste as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
