    score -= 1.5 * item * (1.0 - prn) * (1.0 - prn);

    // Harmonized bins: penalize deviation from mean residual
    let dev = prn - mean_r;
    score += 0.8 * dev * dev;

    // Lookahead: reward leaving room for the next item
    if next > 0.0 {
        let gap = (prn - next).abs();
        score -= 1.2 * (1.0 - gap.min(1.0)) * prn;
        // Exact-fit chaining: next item exactly fills resulting residual
        if next_item_size == post_residual && post_residual > 0 {
            score -= 0.35 * (1.0 + progress);
        }
        // Small chain waste with room for further items
        if next_item_size < post_residual && (post_residual - next_item_size) <= 6 {
            score -= 0.15;
        }
    }

    // Last-chance bin bonus (stronger late in the stream)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Prefer tighter fits overall
    score += 0.5 * item * prn;

    // Fine-grained residual band tuning (mutation of parent's smooth base)
    if post_residual < 8 {
        score -= 0.9; // near-perfect fills
    } else if post_residual <= 12 {
        score += 0.6; // awkward small residual
    } else if post_residual <= 25 {
        score += 0.2;
    } else if post_residual <= 50 {
        score -= 0.15;
    }

    // High fill-ratio bonus: item dominates remaining space
    if bin_residual >= item_size {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        if fill_ratio > 0.85 {
            score -= 1.4 * (fill_ratio - 0.85) / 0.15;
        }
    }

    // New-bin candidate: penalize opening a bin when a decent fit exists,
    // but reward it for large items early when no tight fit is available
    if bin_residual == bin_capacity {
        let tight_exists = post_residual >= item_size && (post_residual - item_size) < 8;
        if tight_exists {
            score += 0.8;
        } else if item_size as f64 > 0.6 * cap && progress < 0.5 {
            score -= 0.3;
        } else {
            score += 0.2 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
