    score += (1.0 - progress) * 0.0 + progress * (norm_pr * norm_pr) * 25.0;

    // Reward tight fits smoothly.
    score -= (item / cap) * (1.0 - norm_pr) * 15.0;

    // Last-chance bonus (smooth sigmoid on fitting_bins_count).
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.5_f64).exp());
    score -= 20.0 * last_chance;

    // Lookahead coupling: prefer bins whose post_residual fits the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Mild pressure toward consolidating open bins.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - norm_pr);

    // New-bin candidate: penalize opening early, allow it when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 - 25.0 * (1.0 - item / cap) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Tiered dead-space shaping (borrowed & tuned from best-known).
    if pr < 10 {
        score -= 45.0;
    } else if pr <= 12 {
        score += 30.0;
    } else if pr <= 25 {
        score += 10.0;
    } else if pr <= 33 {
        score -= 2.0;
    } else if pr <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Tightness reward, nonlinear.
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= tightness * tightness * 25.0;

    // Perfect fit bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure (mild).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0;
        } else if item_size as f64 >= 0.6 * bin_capacity as f64 && pr >= item_size {
            score -= 15.0;
        } else if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 * (1.0 - 0.4 * progress);
        }
        // If next item would chain perfectly into a fresh bin, prefer open bins.
        if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
            score += 12.0;
        }
    }

    // Lookahead chaining.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0;
            }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 {
                score -= 6.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
        } else if pr > 0 {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Fill ratio bonuses.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 6.0 * fill_ratio;
    } else if fill_ratio < 0.35 && pr > item_size {
        score += 3.0;
    }
    if pr >= item_size {
        let tight_fill = item_size as f64 / pr.max(1) as f64;
        if tight_fill > 0.85 {
            score -= 7.0 * (tight_fill - 0.85) / 0.15;
        }
    } else if pr > 0 {
        score += 12.0;
    }

    // Near-exact fit nudge.
    if pr >= item_size && pr - item_size < 4 {
        score -= 4.0;
    }
    // Few-fitting-bins consolidation.
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }
    // Penalize wasteful placement when slack is large and alternatives exist.
    if pr >= item_size && (pr - item_size) as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 1 {
        score += 3.0;
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr as f64) * 0.1;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional fill of the bin after placement.
    let fill = 1.0 - post / cap;
    score -= 40.0 * fill * fill; // reward tight fills quadratically

    // Harmonic classes: post_residual mod 10 / mod 25 buckets.
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;
    // Leftovers in "awkward" classes are penalized.
    let awkward = match m10 {
        1 | 2 | 3 | 7 | 8 | 9 => 1.0,
        _ => 0.0,
    };
    score += 6.0 * awkward;

    // Class of post_residual via integer division thresholds: small dead zones.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Modulo-25 harmonic class: leftover in [25k+1..25k+9] is dead-ish.
    if m25 >= 1 && m25 <= 9 {
        score += 3.0;
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next divides leftover well.
            let ratio = post_residual as f64 / next_item_size as f64;
            if (ratio - ratio.floor()).abs() < 1e-9 && ratio >= 1.0 {
                score -= 15.0; // exact division => perfect future fit
            } else {
                score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            }
            // Penalize if next item barely fits leaving another sliver.
            let next_post = post_residual - next_item_size;
            if next_post > 0 && next_post < 10 {
                score += 5.0;
            }
        } else {
            // Next item won't fit: leftover likely dead space.
            score += 7.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        // Prefer new bin when existing bins have little room or stream is late.
        if crowding < 0.35 || progress > 0.7 {
            score -= 5.0 + 10.0 * (0.35 - crowding.min(0.35));
        } else {
            score += 8.0; // discourage waste when open bins are roomy
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64;

    // Slight preference for bins below mean residual (balance load classes).
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (1..=10) are nearly worthless; penalize them hard.
    let dead_zone = 10u32;
    if post_residual > 0 && post_residual < dead_zone {
        score += (dead_zone - post_residual) as f64 * 25.0;
    }

    // Gaps that cannot fit the known next item are also risky (lookahead-aware).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += next_item_size as f64 * 1.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive if it avoids a very poor fit.
        let poor_fit = (post_residual as f64) > (item_size as f64 * 0.9)
            && post_residual > dead_zone;
        if poor_fit {
            score -= 5.0; // new bin keeps a large usable gap
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    } else {
        // Existing bin: mild reward for being a "last chance" bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins whose residual is already small (tight fits first).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Slight global pressure: fewer open bins relative to progress favors reuse.
    score += open_bins_count as f64 * 0.3
        * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

