    // New-bin candidate: discourage unless it is genuinely better than a poor fit
    if bin_residual == bin_capacity {
        score += 35.0 + 0.2 * item_size as f64;
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).recip();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prn = pr as f64 / cap;
    let item = item_size as f64 / cap;
    let mean_r = mean_residual / cap;
    let next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress
    let mut score = prn * (1.0 + 2.0 * prn) * (1.0 + progress);

    // Non-linear coupling: post residual vs item size interaction
    score -= 1.5 * item * (1.0 - prn) * (1.0 - prn);

    // Harmonized bins: penalize deviation from mean residual
    let dev = prn - mean_r;
    score += 0.8 * dev * dev;

    // Lookahead: reward exact chaining with next item
    if next > 0.0 {
        if prn >= next {
            let chain_waste = prn - next;
            score -= 2.2 * (1.0 - chain_waste.min(1.0)) * prn;
            if chain_waste < 0.05 {
                score -= 1.5 * (1.0 + progress);
            }
            // Perfect chain bonus (absolute residual match)
            if next_item_size == pr {
                score -= 12.0;
