    // Small-bin scarcity bonus: few fitting bins and item fits
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Tight-fit bonus: item fills most of the residual
    if pr >= item_size {
        let tight = item_size as f64 / pr as f64;
        if tight > 0.85 {
            score -= 7.0 * (tight - 0.85) / 0.15;
        }
        // Near-perfect fill: residual left < 4
        if (pr - item_size) < 4 {
            score -= 4.0;
        }
    }

    // Prefer tighter fits overall
    score += 0.5 * item * prn;

    // Absolute residual tiering (fine-grained dead-space control)
    if pr < 10 {
        score -= 20.0;
    } else if pr <= 12 {
        score += 12.0;
    } else if pr <= 25 {
        score += 4.0;
    } else if pr <= 33 {
        score -= 1.0;
    } else if pr <= 50 {
        score -= 3.0;
    }

    // Fill-ratio shaping: reward mostly-full bins, penalize sparse bins
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    if fill_ratio > 0.85 {
        score -= 6.0 * fill_ratio;
    } else if fill_ratio < 0.35 && pr > item_size {
        score += 3.0;
    }

    // New-bin candidate logic: only open a new bin if no tight fit exists
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0;
        } else if pr < item_size {
            score -= 5.0;
        } else {
            score += 6.0 * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && pr >= item_size {
                score += 10.0;
            }
            // Lookahead: opening a bin that chains perfectly with next item is good
            if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
                score -= 12.0;
            }
        }
    }

    // Avoid leaving large dead space when alternatives exist
    if pr >= item_size && (pr - item_size) as f64 > 0.35 * cap && fitting_bins_count > 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
