pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items of size 1..=100.
    // Class A: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 500.0;
        return score;
    }

    // Class B: post_residual too small for the smallest item (dead space).
    if post_residual < 1 {
        score += 200.0;
    }

    // Dead-space class: leftover cannot host next item even though it is >=1.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize proportionally to how "wasted" the leftover is,
        // with a harmonic (1/k) style decay on the leftover size.
        let waste = (next_item_size - post_residual) as f64;
        score += 40.0 + waste * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leftovers that can still host the next item,
        // more so when the leftover is a tight multiple-friendly size.
        score -= 30.0;
        // Harmonic bonus: leftover exactly matches next item (perfect chaining).
        if post_residual == next_item_size {
            score -= 80.0;
        }
    }

    // Integer-division thresholds on post_residual: coarse capacity fractions.
    let q = post_residual / 10; // decile class of leftover
    score += q as f64 * 3.0; // prefer smaller leftover classes

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, unless current
    // bin would leave a large awkward residual.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if item is large relative to capacity, a fresh bin is fine.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 100.0;
        }
    }

    // Modulo coupling: leftover that is a multiple of a common small item
    // size band (10..=20) is more reusable.
    if post_residual % 10 == 0 && post_residual >= 10 {
        score -= 15.0;
    }

    // Late in the stream: prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 25.0;
    }

    // Slight preference for bins below mean residual (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

