    } else if post_residual <= 9 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0; // dead space penalty
    } else if post_residual <= 20 {
        score += 5.0; // moderately wasteful
    } else {
        // Larger residuals may still serve future items: mild reward scaled by size
        score -= (post_residual as f64 - 20.0) * 0.1;
