    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // --- Open bins pressure ---
    // When many bins are open, discourage opening new ones / spreading items thin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current placement would create dead space
    // or the item barely fits nowhere well.
    if bin_residual == bin_capacity {
        let dead_space_risk = post_residual > 0 && post_residual <= 9;
        if dead_space_risk {
            score += 40.0; // don't open a new bin just to create a gap
        } else {
            score += 8.0 + mean_residual * 0.2; // prefer reusing open capacity
        }
