            score += overshoot * 0.35;
        }

        // Two-step combo: if next item also nearly fills the bin after this one,
        // i.e. post_residual ~ next_item_size + something tiny, reward heavily.
        let combo_slack = post_residual as f64 - next_item_size as f64;
        if combo_slack > 0.0 && combo_slack <= 10.0 {
            score -= 15.0 * (1.0 - combo_slack / 10.0);
        }
    }

    // Avoid creating tiny unusable dead space (< 10, min item size).
