    // Many open bins: discourage spreading, prefer filling existing ones.
    if open_bins_count > 2 {
        score += 0.5 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Late in the stream, tighten packing (waste penalized more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

