    if bin_residual == bin_capacity && item_size <= bin_capacity {
        score = post_residual as f64 + 12.0
            - if next_item_size > 0 && next_item_size <= post_residual { 20.0 } else { 0.0 }
            + if fitting_bins_count > 2 { 0.0 } else { 8.0 };
