        score += 5.0;
    }

    // Waste guard: fitting with large leftover when alternatives exist.
    if pr >= item_size && (pr - item_size) as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 1 {
        score += 3.0;
    }

    // Fill-ratio awareness: reward nearly-full bins, keep near-empty open
    // bins flexible for larger future items.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if bin_residual != bin_capacity {
        if fill_ratio > 0.85 {
            score -= 6.0 * fill_ratio;
        } else if fill_ratio < 0.35 && pr >= item_size && fitting_bins_count > 2 {
            score += 3.0;
        }
        if next_item_size > 0 && pr == next_item_size && fill_ratio < 0.5 {
            score -= 4.0;
        }
    }

    // Dead-space escalation in crowded regimes.
    if pr >= item_size && open_bins_count > 6 {
        let dead = (pr - item_size) as f64;
        if dead > 0.45 * bin_capacity as f64 {
            score += 5.0 + 0.04 * dead;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Fine-grained residual shaping
    if post_residual < 10 {
        score -= 45.0;
    } else if post_residual <= 12 {
        score += 30.0;
    } else if post_residual <= 25 {
        score += 10.0;
    } else if post_residual <= 33 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: chain-fit anticipation with graded chain-waste rewards
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let gap = (ni - pr).min(60.0);
            let gap_frac = gap / cap;
            score += 12.0 * gap_frac * gap_frac * cap;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap;
        } else {
            let chain_waste = pr - ni;
            score -= 22.0 - 0.22 * chain_waste;
            if chain_waste == 0.0 {
                score -= 30.0;
                if ni <= 20.0 && fitting_bins_count > 3 {
                    score -= 6.0;
                }
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30.0 {
                score -= 4.0;
            }
            if chain_waste <= 15.0 && ni >= 8.0 {
                score -= 3.0;
            }
            let slack = chain_waste / cap;
            score -= 6.0 * slack * (1.0 - slack);
        }
    }

    // Reward tight fits
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill * (1.0 + progress);

    // Tight fill relative to residual
    if post_residual >= item_size {
        let fill_ratio = item_size as f64 / post_residual as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
        if post_residual - item_size < 4 {
            score -= 4.0;
        }
        if post_residual - item_size <= 2 && item_size >= 25 {
            score -= 5.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Fragmentation penalty vs mean residual
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // High existing fill rewards packing into already-full bins
    let fill_ratio_bin = (bin_capacity - bin_residual) as f64 / cap;
    if fill_ratio_bin > 0.85 {
        score -= 6.0 * fill_ratio_bin;
    } else if fill_ratio_bin < 0.35 && post_residual > item_size {
        score += 3.0;
    }

    // New-bin decision
    if bin_residual == bin_capacity {
        let tight_exists = post_residual >= item_size && (post_residual - item_size) < 8;
        if tight_exists {
            score += 40.0;
        } else if post_residual < item_size {
            score -= 5.0;
        } else {
            score += 6.0 * (1.0 - progress) * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && post_residual >= item_size {
                score += 10.0;
