            if next_item_size > 0 && (next_item_size as f64) <= pr && (pr - next_item_size as f64) < 5.0 {
                score -= 12.0;
            }
            if open_bins_count > 4 && mean_residual > 20.0 {
                score += 8.0;
            }
        }
    }

    // Item cannot fit this bin
    if post_residual > 0 && post_residual < item_size {
        score += 12.0;
    }

    // Penalize large leftover dead space when alternatives exist
    if post_residual >= item_size && (post_residual - item_size) as f64 > 0.35 * cap && fitting_bins_count > 1 {
        score += 3.0;
    }
    if post_residual >= item_size && open_bins_count > 6 {
        let dead = (post_residual - item_size) as f64;
        if dead > 0.45 * cap {
            score += 5.0 + 0.04 * dead;
        }
    }

    // Penalize bins whose residual will be stranded against the lookahead item
    if post_residual >= item_size && post_residual >= 50 && next_item_size > 0 && next_item_size > post_residual {
        score += 5.0;
    }

    score
}

