pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid tiny dead space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize unusable slivers (dead space below min item size ~1, but keep general).
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    } else {
        // Last item: prefer maximal fill.
        score -= 30.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: mild penalty for wasting a scarce residual elsewhere.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: prefer bins with below-average residual (keep large holes open).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be pickier about tight fits; late, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New empty bin candidate: penalize so it is only chosen when everything else is bad.
    if bin_residual == bin_capacity {
        score += 80.0 + 10.0 * open_bins_count as f64;
        // But if item is huge and current bins are fragmented, new bin is cheap.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post residual (tight fit), smoothed polynomial
    let mut score = norm_post * norm_post * (2.0 - norm_post);

    // Non-linear coupling of post residual with stream progress:
    // early on tolerate waste slightly, late in stream penalize dead space more.
    let progress_coupling = norm_post * (1.0 - progress) * (1.0 - progress) * 0.5
        - norm_post * progress * progress * 1.5;
    score += progress_coupling;

    // Reward bins whose residual is well below mean (already fragmented)
    let mean_norm = mean_residual / cap;
    score -= 0.3 * mean_norm * mean_norm;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 1.0;
    } else if fitting_bins_count > 1 {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: penalize if next item fits better in another bin arrangement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits here too: mild reward for leaving usable space
            score -= 0.2 * (nxt / cap);
        } else {
            // dead space for next item: penalty growing with gap
            score += 0.3 * ((nxt - pr) / cap);
        }
    }

    // Slight penalty for spreading across many bins when progress is low
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes of capacity fractions.
    let quarter = bin_capacity / 4; // 25
    let half = bin_capacity / 2;    // 50
    let post = post_residual;

    // Dead-space penalty: residuals in awkward classes are hard to fill.
    if post == 0 {
        score -= 40.0; // perfect fit, ideal
    } else if post < 10 {
        score += 8.0; // tiny sliver, near-wasted
    } else if post % quarter == 0 {
        score -= 6.0; // perfectly divisible class (25/50/75) — reusable
    } else if post % 10 == 0 {
        score -= 3.0; // decade class, common item sizes fit
    } else if post > half {
        score -= 2.0; // still roomy
    } else {
        score += 4.0 * (1.0 - (post as f64) / half as f64); // mid-range awkwardness
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 25.0;
        } else if next_item_size <= post {
            // harmonic coupling: does next item land post_residual in a good class?
            let nxt_post = post - next_item_size;
            if nxt_post % quarter == 0 || nxt_post == 0 {
                score -= 10.0;
            } else if nxt_post < 10 {
                score += 5.0;
            }
        } else {
            score += 3.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // existing bins with good fits, but it must beat poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
    } else {
        // Tightness reward: the fuller the bin already was, the better.
        let fill = 1.0 - (bin_residual as f64) / cap;
        score -= 10.0 * fill * fill;
    }

    // Mean residual coupling: when open bins are on average roomy, prefer
    // consolidating into them rather than spreading.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

