    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (>=10, or
    // >=1 under unknown distribution) can use are worthless. Penalize gaps
    // that fall below the smallest plausible item size.
    let min_item = 1u32;
    if post_residual < 10 && post_residual >= min_item {
        // Small unusable gap: penalize heavily, worse the smaller the gap.
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual >= 10 {
        // Usable gap: mild reward for leaving room that fits a typical item.
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this placement; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But allow opening a new bin early in the stream when few bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress) * (1.0 - open_bins_count.min(10) as f64 / 10.0);
    } else {
        // Favor bins that are already relatively full (low residual relative to mean).
        if mean_residual > 0.0 && (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Dead-space avoidance: tiny residuals are nearly worthless dead space —
    // reward them hard (oracle minimizes score).
    if pr > 0 && pr < 10 {
        score -= 45.0;
    } else if pr <= 12 {
        score += 30.0;
    } else if pr <= 25 {
        score += 10.0;
    } else if pr <= 33 {
        score -= 2.0;
    } else if pr <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead chain scoring: residuals that host the next item are valuable.
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0;
                if next_item_size <= 20 && fitting_bins_count > 3 {
                    score -= 6.0;
                }
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
            if chain_waste <= 15.0 && next_item_size >= 8 {
                score -= 3.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Perfect fill reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Tight fill reward.
    if pr >= item_size {
        let tight_fill = item_size as f64 / pr as f64;
        if tight_fill > 0.85 {
            score -= 7.0 * (tight_fill - 0.85) / 0.15;
        }
        if pr - item_size <= 2 && item_size >= 25 {
            score -= 5.0;
        }
        if pr - item_size < 4 {
            score -= 4.0;
        }
    } else if pr > 0 {
        score += 12.0;
    }

    // Last-chance bin bonus.
    if bin_residual != bin_capacity && fitting_bins_count == 1 {
        score -= 12.0;
    }
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: open a bin only when it avoids a poor fit
    // or when existing residuals are unusable, weighted by stream progress.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        let poor_fit = pr > item_size * 9 / 10 && pr > 10;
        let scarcity = fitting_bins_count <= 1 && mean_residual < 15.0;
        if tight_exists {
            score += 40.0;
        } else if poor_fit || scarcity {
            score -= 5.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
            if item_size as f64 >= 0.6 * bin_capacity as f64 && pr >= item_size {
                score += 10.0;
            }
            if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
                score -= 12.0;
            }
            if open_bins_count > 4 && mean_residual > 20.0 {
                score += 8.0;
            }
        }
    }

    // Prefer bins whose residual is already small.
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Consolidation pressure as the stream progresses.
    score += open_bins_count as f64 * 0.3 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Mid-range dead space that common sizes can't use.
    if pr >= 30 && pr <= 60 && next_item_size > 0 && next_item_size > pr {
        score += 5.0;
    }

    // Waste guard when alternatives exist.
    if pr >= item_size && (pr - item_size) as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 1 {
        score += 3.0;
    }

    // Fill-ratio awareness.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if bin_residual != bin_capacity {
        if fill_ratio > 0.85 {
            score -= 6.0 * fill_ratio;
        } else if fill_ratio < 0.35 && pr >= item_size && fitting_bins_count > 2 {
            score += 3.0;
        }
        if next_item_size > 0 && pr == next_item_size && fill_ratio < 0.5 {
            score -= 4.0;
        }
    }

    // Dead-space escalation in crowded regimes.
    if pr >= item_size && open_bins_count > 6 {
        let dead = (pr - item_size) as f64;
        if dead > 0.45 * bin_capacity as f64 {
            score += 5.0 + 0.04 * dead;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the post-residual exactly matches the next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect chain: next item fits exactly
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Next item can still fit comfortably
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // dead space penalty scaled by how much the next item would waste
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fill
        score -= 40.0;
    }

    // Compare post_residual against mean residual: prefer leaving typical gaps
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Reward high fill ratio
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // barely usable
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward heavily; if next item would be stranded, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item can't go here; mild penalty scaled by how much is wasted
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item fits here: reward proportional to resulting tightness
            let rem2 = post_residual - next_item_size;
            score -= 6.0 * (1.0 - rem2 as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residual space flexible); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 20.0 * (1.0 - progress) - 15.0 * progress;
        // Penalize new bins when many are already open.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Favor existing bins more as stream progresses.
        score -= 8.0 * progress;
    }

    // Global state: if mean residual is high, prefer bins below the mean
    // (consume the outliers); if low, prefer bins above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff * (if progress > 0.5 { 1.0 } else { -1.0 });

    // Mild preference for fuller bins overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let coupling = base * (1.0 + 0.8 * prog2 + 0.4 * progress * base);

    // Reward tight fits: penalize (subtract) when post_residual is small
    let mut score = coupling * cap;

    // Penalize large dead space quadratically late in the stream
    score += 2.5 * base * base * cap * (0.5 + progress);

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        // Mild penalty when many alternatives exist, scaled by residual
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 2.0 * base;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = (pr - ns) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            score += 8.0 * ((ns - pr) / cap);
        }
    }

    // Deviation from mean residual: prefer bins near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // Prefer fuller bins (low residual) slightly
    score += 0.05 * pr as f64;

    // New-bin candidate: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let tight = if mean_residual > 0.0 { (mean_residual / cap).min(1.0) } else { 1.0 };
        score = 55.0 + 45.0 * (1.0 - tight) + 20.0 * progress;
    }

    score
}

