            score -= 25.0 + 15.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + gap * 0.15;
        }
    }

    // Compare against mean residual: favor bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a loose fit.
    if fitting_bins_count == 1 {
        score -= 6.0 * fit_ratio;
        if post_residual < 10 {
            score -= 5.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline, penalize so open bins with tight fits win.
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pair fits nicely in a fresh bin: make fresh bin competitive.
            score -= 18.0;
        }
    }

    // Late in the stream, consolidate: prefer reusing existing bins over opening more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    } else {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
