        score += (dead_zone - pr) as f64 * 25.0;
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead: chain the next item into this residual when possible.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Tight fill reward: item nearly fills the resulting residual.
    if pr >= item_size {
        let tight_fill = item_size as f64 / pr as f64;
        if tight_fill > 0.85 {
            score -= 7.0 * (tight_fill - 0.85) / 0.15;
        }
    }
    if pr >= item_size && pr - item_size <= 2 && item_size >= 25 {
        score -= 5.0;
    }

    // Open-bin pressure / new-bin candidate handling.
    if bin_residual == bin_capacity {
        let poor_fit = pr > item_size * 9 / 10 && pr > dead_zone;
        if poor_fit {
            score -= 5.0; // new bin keeps a large usable gap
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    } else {
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        score += (bin_residual as f64 - pr as f64) * 0.1;
    }

    // Consolidation pressure grows as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // High-fill bins get a bonus to finish them off.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 6.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
