    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * t;
    }

    // Prefer bins whose residual deviates favorably from the mean: tighter-than-average bins get priority.
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Penalize mismatch between item size and available space (encourage size-matched placement).
    score += 0.06 * (item_size as f64 - bin_residual as f64).abs();

    // New empty bin candidate: mildly discourage early (consolidate), encourage late (fresh capacity fine).
    if bin_residual == bin_capacity {
        score += 14.0 * (1.0 - t) - 6.0 * t;
        // If no open bin fits well, the base post_residual already makes this competitive.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
