pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover too small for the minimum item size (1..100 unknown,
    // but assume small items exist). Penalize tiny but nonzero leftovers strongly.
    if post_residual > 0 && post_residual <= 5 {
        score += 60.0;
    }

    // Harmonic class via integer division: post_residual / 10 classes.
    // Leftovers in the class [40, 50) are the most reusable (fit half the range),
    // give them a bonus; leftovers in [90, 100) are nearly a fresh bin, fine too.
    let class = post_residual / 10;
    match class {
        0 => score += 40.0,          // 0..9: nearly dead space
        1 => score += 25.0,          // 10..19: only tiny items fit
        2 => score += 15.0,          // 20..29
        3 => score += 5.0,           // 30..39
        4 => score -= 20.0,          // 40..49: golden class
        5 => score += 0.0,           // 50..59
        6 => score -= 5.0,           // 60..69
        7 => score -= 10.0,          // 70..79
        8 => score -= 15.0,          // 80..89
        _ => score -= 10.0,          // 90+: almost empty bin
    }

    // Coupling with next item (lookahead): reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact next-fit harmony: post_residual - next_item_size small is great.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 300.0;
            } else if gap <= 10 {
                score -= 50.0;
            } else {
                score -= 10.0 * (1.0 - gap as f64 / cap);
            }
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall.
            let shortfall = next_item_size - post_residual;
            score += 0.5 * shortfall as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid wasting this bin's remaining capacity).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it moderately
    // attractive only when existing bins would leave bad leftovers.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (mildly grows with open bin count).
        score = cap - (pr / cap) * 10.0 + 30.0 + (open_bins_count as f64).sqrt() * 2.0;
        // If current item + next item pack perfectly in a fresh bin, reward it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity
            && bin_capacity - item_size - next_item_size <= 5 {
            score -= 250.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
    }

    // Mean-residual coupling: when open bins are generally empty, prefer filling
    // existing bins (penalize new bins implicitly via score already); when mean
    // residual is low, tighten selection by amplifying post_residual differences.
    let mr = mean_residual;
    if mr > 0.0 {
        score *= 1.0 + 0.3 * (pr / (mr + pr + 1.0));
    }

    // Slight preference for tighter fits overall (best-fit flavor).
    score += 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    // Items in [1,100]; anything below 10 is nearly unusable dead space.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 15 {
        score += 10.0;
    }

    // Perfect fit reward: strongly favor bins that close exactly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post residual, this placement
    // enables a chain — reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post residual too small for the known next item: penalize as dead space.
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize creating tight gaps when many bins are already open,
    // encouraging consolidation into fewer bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual > 0 && post_residual < item_size {
        score += pressure * 2.5;
    }

    // Mild reward for using bins with larger residual (fill emptier bins first
    // keeps tight bins available for tight items).
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for keeping scores comparable to new-bin candidate
    // (new bin call has post_residual == bin_capacity - item_size, which is
    // naturally large; subtract a small constant to make open bins competitive).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let dead_zone = 10u32;
    if pr > 0 && pr < dead_zone {
        score += (dead_zone - pr) as f64 * 25.0;
    }

    // Lookahead: reward bins whose leftover fits the next item tightly (chain packing).
    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 20.0 - 0.2 * chain_waste;
            if pr == next_item_size {
                score -= 28.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
        } else {
            // Gap that cannot fit the next item: risky, penalize by shortfall.
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    } else if pr > 0 && pr < next_item_size.max(1) {
        score += next_item_size as f64 * 1.5;
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Tightness reward: item nearly fills the residual.
    if pr >= item_size {
        let tight_fill = item_size as f64 / pr as f64;
        if tight_fill > 0.85 {
            score -= 7.0 * (tight_fill - 0.85) / 0.15;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let poor_fit = pr > item_size && (pr - item_size) as f64 > 0.35 * bin_capacity as f64;
        if poor_fit {
            // Opening a new bin preserves a large usable gap.
            score -= 5.0;
            if item_size as f64 >= 0.6 * bin_capacity as f64 {
                score -= 10.0; // large items do better alone
            }
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64;
        }
    } else {
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        if fitting_bins_count <= 2 && pr >= item_size {
            score -= 8.0;
        }
        score += (bin_residual as f64 - pr as f64) * 0.1;
    }

    // Consolidation pressure: fewer open bins relative to progress favors reuse.
    score += open_bins_count as f64 * 0.3
        * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Late-stream pressure: with many open bins, penalize leaving large dead space.
    if pr >= item_size && open_bins_count > 6 {
        let dead = (pr - item_size) as f64;
        if dead > 0.45 * bin_capacity as f64 {
            score += 5.0 + 0.04 * dead;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 200.0; // perfect two-item packing
        } else if diff <= 5 {
            score -= 60.0 + (5 - diff) as f64 * 8.0;
        } else {
            // penalize leaving residual that next item can't use well
            score += diff as f64 * 0.15;
        }
        // If next item can't fit into post_residual, dead space is created
        if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: prefer minimal waste
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if perfect lookahead match exists even in fresh bin, allow it
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Prefer filling bins with small residuals (avoid many tiny open bins)
    if post_residual < 10 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Dead-space avoidance: heavy penalty for tiny unusable gaps.
    if pr > 0 && pr < 20 {
        score += (20.0 - pr as f64) * 6.0;
    } else if pr >= 20 && pr <= 25 {
        score += 10.0;
    } else if pr <= 33 {
        score -= 2.0;
    } else if pr <= 50 {
        score -= 8.0;
    } else {
        score -= 4.0;
    }

    // Tightness reward, nonlinear.
    let tightness = 1.0 - (pr as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit bonus.
    if pr == 0 {
        score -= 100.0;
    }

    // Last-chance bin: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure (mild).
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0; // an open bin fits nearly perfectly; never open new
        } else if item_size >= bin_capacity / 2 {
            score -= 10.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 25.0 * (1.0 - 0.4 * progress);
        }
        if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
            score -= 12.0;
        }
    }

    // Lookahead: reward placements that let the next item chain into this bin.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size {
                score -= 30.0; // perfect chain
            }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 {
                score -= 6.0;
            }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
            if chain_waste <= 15.0 && next_item_size >= 8 {
                score -= 3.0;
            }
            if chain_waste > 5.0 && chain_waste <= 12.0 && mean_residual > (pr as f64) * 1.5 {
                score -= 2.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Fill ratio bonus: strong fits into the current residual.
    if pr >= item_size {
        let fill_ratio = item_size as f64 / pr.max(1) as f64;
        if fill_ratio > 0.85 {
            score -= 7.0 * (fill_ratio - 0.85) / 0.15;
        }
        if (pr - item_size) < 4 {
            score -= 4.0;
        }
        // Near-perfect fit of a sizable item.
        if (pr - item_size) <= 2 && item_size >= 25 {
            score -= 5.0;
        }
        // Large leftover relative to capacity is wasteful when alternatives exist.
        if (pr - item_size) as f64 > 0.35 * bin_capacity as f64 && fitting_bins_count > 1 {
            score += 3.0;
        }
        // Dead-space pressure when many bins are open.
        if open_bins_count > 6 {
            let dead = (pr - item_size) as f64;
            if dead > 0.45 * bin_capacity as f64 {
                score += 5.0 + 0.04 * dead;
            }
        }
    } else if pr > 0 {
        score += 12.0; // creates a gap smaller than the item itself
    }

    // Prefer fuller existing bins.
    let fill_ratio_bin = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio_bin > 0.85 {
        score -= 6.0 * fill_ratio_bin;
    } else if fill_ratio_bin < 0.35 && pr > item_size {
        score += 3.0;
    }
    if next_item_size > 0 && pr == next_item_size && fill_ratio_bin < 0.5 {
        score -= 4.0;
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - pr as f64) * 0.1;
    score -= progress * 5.0 * tightness;

    // Few-fitting-bins consolidation pressure.
    if fitting_bins_count <= 2 && pr >= item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: waste ratio of the bin after placement.
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fill_fraction * (bin_residual as f64);

    // Penalize leaving dead space that no future item (>= 10) can use.
    if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item can still fit in the post residual,
    // reward; if this placement would block the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            score += 5.0;
        }
        // Reward pairing: item + next item almost exactly fill the bin.
        let pair = item_size as f64 + next_item_size as f64;
        if (pair - bin_residual as f64).abs() <= 2.0 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when existing bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = mean_residual / bin_capacity as f64;
        // Penalize new bins more as stream progresses and bins are open.
        score += 25.0 + 20.0 * progress + 15.0 * (1.0 - crowdedness);
        // But if no bin fits well (post residual would be large elsewhere),
        // new bin becomes relatively better: soften penalty when item is large.
        if item_size >= 70 {
            score -= 20.0;
        }
    } else {
        // Prefer bins with smaller residual overall (best-fit bias).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Fine-grained post_residual shaping (borrowed tiers).
    if pr < 10 { score -= 45.0; }
    else if pr <= 12 { score += 30.0; }
    else if pr <= 25 { score += 10.0; }
    else if pr <= 33 { score -= 2.0; }
    else if pr <= 50 { score -= 8.0; }
    else { score -= 4.0; }

    // 2-step lookahead with graded chain rewards.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.22 * chain_waste;
            if pr == next_item_size { score -= 30.0; }
            if chain_waste == 0.0 && next_item_size <= 20 && fitting_bins_count > 3 { score -= 6.0; }
            if chain_waste > 0.0 && chain_waste <= 5.0 && pr <= 30 { score -= 4.0; }
            if chain_waste <= 15.0 && next_item_size >= 8 { score -= 3.0; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.30 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Compare against mean residual: favor bins tighter than average.
    score += (mean_residual - pr as f64) * 0.3;

    // Last-chance bin handling.
    if fitting_bins_count == 1 {
        score -= 6.0 * fit_ratio;
        if pr < 10 { score -= 5.0; }
    }
    if fitting_bins_count <= 2 && pr >= item_size { score -= 8.0; }

    // Near-perfect fill bonuses.
    if pr >= item_size && pr - item_size < 4 { score -= 4.0; }
    if pr >= item_size && (pr - item_size) <= 2 && item_size >= 25 { score -= 5.0; }
    if pr > 0 && pr < item_size { score += 12.0; }

    // Fill-ratio shaping.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    if fill_ratio > 0.85 { score -= 6.0 * fill_ratio; }
    else if fill_ratio < 0.35 && pr > item_size { score += 3.0; }

    // Tight-fit gradient.
    if pr >= item_size {
        let tight_fill = item_size as f64 / pr as f64;
        if tight_fill > 0.85 { score -= 7.0 * (tight_fill - 0.85) / 0.15; }
        let dead = (pr - item_size) as f64;
        if dead > 0.35 * cap && fitting_bins_count > 1 { score += 3.0; }
        if open_bins_count > 6 && dead > 0.45 * cap { score += 5.0 + 0.04 * dead; }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0;
        } else if pr < item_size {
            score -= 5.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && pr >= item_size { score += 10.0; }
            if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 { score -= 12.0; }
            if open_bins_count > 4 && mean_residual > 20.0 { score += 8.0; }
        }
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity { score -= progress * 4.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: raw post residual
    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress.
    // Early stream: prefer filling bins fully (penalize residual strongly, super-linear).
    // Late stream: residual penalty softens (accept leftover space).
    let p = 1.0 + 3.0 * (1.0 - progress);
    score += 40.0 * norm_post.powf(p) * cap * (1.0 - progress);

    // Cubic interaction: dead space near half-capacity is worst (hard to fill later).
    let half = norm_post - 0.5;
    score += 30.0 * half * half * half * half * cap;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 0.5 * post;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tight = 1.0 - (post - nxt) / cap;
            score -= 25.0 * tight;
        } else {
            score += 15.0 * (nxt - post) / cap;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 10.0 * (post - mean_residual) / cap;

    // Mild penalty for proliferating bins.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: keep neutral-ish, slightly discouraged so good fits win.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (<= 10 or exact fractions of capacity) are
    // effectively sealed; larger leftovers remain reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division thresholds on post_residual (classes of 10)
    let class = post_residual / 10;
    match class {
        0 => score -= 12.0,          // near-perfect seal, excellent
        1 => score -= 6.0,           // small dead space, acceptable
        2 => score += 1.0,           // 20..29: awkward zone
        3 => score += 3.0,           // 30..39: awkward zone
        4 => score -= 2.0,           // 40..49: half-bin class, reusable
        5 => score -= 3.0,           // ~half capacity left
        6 => score -= 4.0,
        7 => score -= 5.0,
        8 => score -= 6.0,
        9 => score -= 7.0,
        _ => {}                       // nearly empty bin, fine
    }

    // Exact fraction harmonics: residuals equal to common divisors of 100
    if post_residual == 0 { score -= 20.0; }
    if post_residual == 50 || post_residual == 25 || post_residual == 20 || post_residual == 10 {
        score -= 5.0;
    }

    // Modulo coupling with next item: reward if next item divides into post_residual
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= post_residual {
            // next item fits: strong reward, especially exact division
            score -= 8.0;
            if post_residual % n == 0 { score -= 6.0; }
            // harmonic class match: next item in same 10-class as residual
            if (n / 10) == (post_residual / 10) { score -= 2.0; }
        } else {
            // next item cannot use the leftover: penalize wasted space
            score += 4.0;
            if post_residual > 0 && post_residual < 10 { score -= 6.0; } // sealed anyway
        }
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive late in the stream or
    // when open bins are nearly full on average
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = mean_residual / cap;
        // penalize new bin early; relax when mean residual is low (bins crowded)
        score += 30.0 * (1.0 - progress) + 40.0 * openness;
        if next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0; // future items are big, fresh capacity valuable
        }
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.3;

    // Tie-break: prefer tighter fit via residual-to-capacity ratio
    score += (bin_residual as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Tight-fit reward ladder (mutated thresholds).
    if pr < 8 {
        score -= 40.0;
    } else if pr <= 12 {
        score += 28.0;
    } else if pr <= 25 {
        score += 8.0;
    } else if pr <= 40 {
        score -= 6.0;
    } else {
        score -= 3.0;
    }

    // Base tightness term.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Lookahead: reward bins that can chain the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let chain_waste = (pr - next_item_size) as f64;
            score -= 22.0 - 0.20 * chain_waste;
            if pr == next_item_size {
                score -= 28.0;
            }
            if chain_waste <= 5.0 && pr <= 30 {
                score -= 4.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let gap_penalty = if fitting_bins_count <= 2 { 0.40 } else if fitting_bins_count <= 4 { 0.34 } else { 0.28 };
            score += gap_penalty * gap.min(60.0);
        }
    }

    // Mean-residual comparison.
    score += (mean_residual - pr as f64) * 0.25;

    // Last-chance bin handling.
    if fitting_bins_count == 1 && pr >= item_size {
        score -= 6.0 * fit_ratio;
        if pr - item_size < 4 {
            score -= 5.0;
        }
    }

    // Nearly exact fill bonus.
    if pr >= item_size && pr - item_size <= 2 && item_size >= 20 {
        score -= 6.0;
    }

    // High-fill bins: protect them.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    if fill_ratio > 0.85 {
        score -= 6.0 * fill_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let tight_exists = pr >= item_size && (pr - item_size) < 8;
        if tight_exists {
            score += 40.0; // an open bin is nearly perfect, keep fresh bin unattractive
        } else if pr < item_size {
            score -= 5.0;
        } else {
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * (1.0 - progress);
            if item_size as f64 >= 0.6 * cap && pr >= item_size {
                score += 10.0;
            }
            if next_item_size > 0 && next_item_size <= pr && (pr - next_item_size) < 5 {
                score -= 12.0;
            }
            if open_bins_count > 4 && mean_residual > 20.0 {
                score += 8.0;
            }
        }
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 4.0;
    }

    // Avoid leaving large unusable gaps when alternatives exist.
    if pr >= item_size && (pr - item_size) as f64 > 0.35 * cap && fitting_bins_count > 1 {
        score += 3.0;
    }
    if pr >= item_size && open_bins_count > 6 {
        let dead = (pr - item_size) as f64;
        if dead > 0.45 * cap {
            score += 5.0 + 0.04 * dead;
        }
    }

    score
}

